mapper.select:
select REDEMPTION_ID redemptionId, DATA_STATUS dataStatus, PROD_REGIST_NO prodRegistNo, PROD_ID prodId, IS_SALES_AGENCY isSalesAgency, TRIGGER_REMARK triggerRemark, REJECT_REMARK rejectRemark, RPT_ISSUE_DATE rptIssueDate, DEAL_DATE dealDate, UPDATE_TIME updateTime, UPDATE_USER updateUser, TO_CHAR(UPDATE_TIME,'YYYY-MM-DD HH24:MI:SS') updateTimeStr from DIS_LARGE_REDEMPTION
AND PROD_REGIST_NO in
#{item}
AND PROD_ID in
#{item}
AND DATA_STATUS=#{dataStatus}
AND RPT_ISSUE_DATE >= TO_DATE(#{rptIssueDateStart},'YYYY-MM-DD')
AND RPT_ISSUE_DATE <= TO_DATE(#{rptIssueDateEnd},'YYYY-MM-DD')
order by UPDATE_TIME desc

select PROD_REGIST_NO
from DIS_PROD_ADJUST
where PROD_REGIST_NO = #{prodRegistNo,jdbcType=VARCHAR}

select count(1) from (
     select * from rep_prod_info where
     PROD_ID = #{prodId,jdbcType=VARCHAR} and
    PROD_RE = #{prodRegistNo,jdbcType=VARCHAR}
) aa
